 17	// handleCreateResource handles 'ctrl+n' key - start unified group/project creation.
 18	// Stashes parent info and loads templates from OCI registry before showing form.
 19	func (m Model) handleCreateResource() (tea.Model, tea.Cmd) {
 20		// GetShortcuts greys N while the level is loading, and Rule 130 forbids
 21		// greying a key that acts anyway. It matters more than the tidiness: the
 22		// parent's ID is read below, and a level still loading has none to give —
 23		// the form would open under an empty parent and create at the root.
 24		if m.loading {
 25			return m, m.footer.Warn(reasonStillLoading)
 26		}
 27	
 28		// Use the currently browsed group as parent, not the selected item.
 29		// currentGroupNode is nil at root level.
 30		parentName := ""
 31		parentID := ""
 32	
 33		if m.currentGroupNode != nil {
 34			parentName = m.currentGroupNode.FullPath
 35			parentID = m.currentGroupNode.ID
 36		}
 37	
 38		// Stash parent info for after template loading
 39		m.creationParentName = parentName
 40		m.creationParentID = parentID
 41		m.mode = ModeLoadingTemplates
 42	
 43		return m, m.loadTemplates()
 44	}
