 46	// registryPassword reads the template registry's password from the secret
 47	// store, keyed by the registry URL.
 48	//
 49	// It used to be config.Registry.Password — plaintext YAML, read on every
 50	// template listing. The field is gone; a value left there by an older version
 51	// was moved into the store at startup (§3.9).
 52	//
 53	// An empty result is not an error: an anonymous registry is the common case,
 54	// and oci.NewClient treats empty credentials as "do not authenticate".
 55	func (m Model) registryPassword() string {
 56		if m.shared == nil || m.shared.Secrets.Storage == nil || m.config.Registry.URL == "" {
 57			return ""
 58		}
 59		password, err := m.shared.Secrets.Storage.Load(m.config.Registry.URL)
 60		if err != nil {
 61			return ""
 62		}
 63		return password
 64	}
