 66	// loadTemplates loads available templates from the OCI registry catalog.
 67	// Degrades gracefully: returns empty list if registry is not configured or on error.
 68	func (m Model) loadTemplates() tea.Cmd {
 69		registryURL := m.config.Registry.URL
 70		basePath := m.config.Registry.TemplatesRepository
 71		username := m.config.Registry.Username
 72		password := m.registryPassword()
 73	
 74		return func() tea.Msg {
 75			// If registry not configured, return empty (graceful degradation)
 76			if registryURL == "" || basePath == "" {
 77				return TemplatesLoadedMsg{}
 78			}
 79	
 80			client := oci.NewClient(registryURL, username, password)
 81			entries, err := client.ListTemplates(basePath)
 82			if err != nil {
 83				log.Printf("ERROR: failed to load templates from OCI registry: %v", err)
 84				return TemplatesLoadedMsg{Error: err}
 85			}
 86	
 87			return TemplatesLoadedMsg{Templates: entries}
 88		}
 89	}
