116	// handleCreationSubmit handles form submission.
117	//
118	// The row goes on screen before the request goes out: creating is a network
119	// call, and the tree used to be emptied by a full refresh for the whole of it —
120	// the user saw a blank table and a silent footer, with nothing to say the thing
121	// they had just asked for was on its way. The row is the answer, and the
122	// registry is what keeps it honest (see jobs.go).
123	func (m Model) handleCreationSubmit(msg components.CreationFormSubmitMsg) (tea.Model, tea.Cmd) {
124		m.mode = ModeNormal
125		m.creationForm = nil
126	
127		if m.shared.Forge == nil {
128			m.error = "Not connected to a forge"
129			return m, nil
130		}
131	
132		target := m.createTarget(msg)
133		if m.busy(target) {
134			return m, m.footer.Warn(busyMessage)
135		}
136	
137		nodeType := NodeTypeProject
138		work := m.createProject(msg, target)
139		if msg.FormType == components.FormTypeGroup {
140			nodeType = NodeTypeGroup
141			work = m.createGroup(msg, target)
142		}
143	
144		m.insertCreatingNode(msg, target, nodeType)
145		return m, jobs.Start(createRun(target, msg.Name), work)
146	}
147	
148	// createTarget is the path the row and the run are both keyed on, predicted
149	// from the parent being browsed and the slug the name becomes.
150	//
151	// A prediction, because the forge answers with the real one and is free to
152	// differ — but the row has to exist before there is an answer, so it needs a
153	// key that can be computed now. settleCreating is what reconciles the two.
154	func (m Model) createTarget(msg components.CreationFormSubmitMsg) string {
155		slug := slugify(msg.Name)
156		if m.creationParentName == "" {
157			return slug
158		}
159		return m.creationParentName + "/" + slug
160	}
