162	// insertCreatingNode puts the placeholder at the level being browsed.
163	//
164	// At the end of the level rather than sorted in: the default is the forge's own
165	// order, which is insertion order, so the row appears where a reader's eye is
166	// free — the bottom — instead of displacing rows above the cursor. Under a sort
167	// the table places it like any other row.
168	func (m *Model) insertCreatingNode(msg components.CreationFormSubmitMsg, target string, nodeType NodeType) {
169		node := &TreeNode{
170			Name:       msg.Name,
171			FullPath:   target,
172			Type:       nodeType,
173			Creating:   true,
174			Visibility: msg.Visibility,
175			Parent:     m.currentGroupNode,
176		}
177		if m.currentGroupNode == nil {
178			m.nodes = append(m.nodes, node)
179		} else {
180			m.currentGroupNode.Children = append(m.currentGroupNode.Children, node)
181		}
182		m.updateTableRows()
183	}
184	
185	// replaceCreating swaps the placeholder keyed on target for what the forge
186	// answered, or drops it when replacement is nil.
187	//
188	// It walks the loaded tree rather than the current level: the user is free to
189	// drill elsewhere while the request is in flight, and the row belongs to the
190	// level it was made in.
191	func replaceCreating(nodes []*TreeNode, target string, replacement *TreeNode) ([]*TreeNode, bool) {
192		for i, node := range nodes {
193			if node.Creating && node.FullPath == target {
194				if replacement == nil {
195					return append(nodes[:i], nodes[i+1:]...), true
196				}
197				replacement.Parent = node.Parent
198				nodes[i] = replacement
199				return nodes, true
200			}
201			if children, ok := replaceCreating(node.Children, target, replacement); ok {
202				node.Children = children
203				return nodes, true
204			}
205		}
206		return nodes, false
207	}
208	
209	// carryOverCreating keeps the placeholders of a level that is being replaced.
210	//
211	// A reload swaps the level wholesale — `ctrl+r` at the root, a ChildrenLoadedMsg
212	// inside a group — and a create still in flight has nothing yet to be replaced
213	// by. Dropped here, its row would vanish mid-request while the registry went on
214	// tracking the run: `:jobs` would show work the tree had stopped admitting to,
215	// and settleCreating would have nothing left to resolve when the answer came.
216	func carryOverCreating(previous, fresh []*TreeNode) []*TreeNode {
217		for _, node := range previous {
218			if node.Creating {
219				fresh = append(fresh, node)
220			}
221		}
222		return fresh
223	}
224	
225	// settleCreating resolves the placeholder and rebuilds the rows.
226	func (m *Model) settleCreating(target string, replacement *TreeNode) {
227		m.nodes, _ = replaceCreating(m.nodes, target, replacement)
228		m.updateTableRows()
229	}
