231	// selectRow puts the cursor on the row for path, if it is on screen. It is what
232	// replaces the pendingSelectPath round trip: the node is already in the tree,
233	// so there is no refresh to wait for and no path to chase.
234	func (m *Model) selectRow(path string) {
235		for i, row := range m.table.Visible() {
236			if row.node.FullPath == path {
237				m.table.SetCursor(i)
238				return
239			}
240		}
241	}
