243	// createGroup creates a new namespace on the forge.
244	func (m Model) createGroup(msg components.CreationFormSubmitMsg, target string) tea.Cmd {
245		backend := m.shared.Forge
246		spec := forge.NewNamespace{
247			Name:        msg.Name,
248			Slug:        slugify(msg.Name),
249			Description: msg.Description,
250			Visibility:  msg.Visibility,
251			ParentID:    msg.ParentID,
252		}
