268	// createProject creates a new repository and optionally applies a template.
269	//
270	// The template apply is inside the same command, and therefore inside the same
271	// run item: it is several more requests — a download and an initial commit — and
272	// splitting them would put a row back to idle while the slower half was still
273	// going.
274	func (m Model) createProject(msg components.CreationFormSubmitMsg, target string) tea.Cmd {
275		backend := m.shared.Forge
276		spec := forge.NewRepository{
277			Name:        msg.Name,
278			Slug:        slugify(msg.Name),
279			Description: msg.Description,
280			Visibility:  msg.Visibility,
281			NamespaceID: msg.ParentID,
282		}
283		registryURL := m.config.Registry.URL
284		username := m.config.Registry.Username
285		password := m.registryPassword()
286	
287		// Resolve template entry from display name
288		var templateRepo, templateTag string
289		if msg.Template != "" {
290			for _, entry := range m.templateEntries {
291				if entry.Name == msg.Template {
292					templateRepo = entry.Repository
293					templateTag = entry.Tag
294					break
295				}
296			}
297		}
298	
299		return func() tea.Msg {
300			repo, err := backend.CreateRepository(context.Background(), spec)
301			if err != nil {
302				return ProjectCreatedMsg{Target: target, Error: err}
303			}
304	
305			// Apply template if one was selected and resolved
306			if templateRepo != "" {
307				templateErr := applyTemplate(backend, repo.ID, registryURL, username, password, templateRepo, templateTag)
308				if templateErr != nil {
309					return ProjectCreatedMsg{Repository: repo, Target: target, TemplateError: templateErr}
310				}
311			}
312	
313			return ProjectCreatedMsg{Repository: repo, Target: target}
314		}
315	}
