317	// applyTemplate downloads an OCI template and commits its files to the project.
318	// This is a standalone function (not a method) because it runs inside a goroutine.
319	func applyTemplate(backend forge.Forge, repositoryID string, registryURL, username, password, repository, tag string) error {
320		ociClient := oci.NewClient(registryURL, username, password)
321	
322		tmpl, err := ociClient.DownloadTemplate(repository, tag)
323		if err != nil {
324			return fmt.Errorf("download template: %w", err)
325		}
326	
327		// Convert template files to commit actions
328		files := make([]forge.FileChange, 0, len(tmpl.Files))
329		for filePath, content := range tmpl.Files {
330			files = append(files, forge.FileChange{
331				Action:  forge.FileCreate,
332				Path:    filePath,
333				Content: content,
334			})
335		}
336	
337		if len(files) == 0 {
338			return nil
339		}
340	
341		return backend.InitialCommit(context.Background(), repositoryID, files)
342	}
