344	// handleGroupCreated resolves the placeholder row in place.
345	//
346	// No refresh: the forge has just told us what it made, so re-listing the whole
347	// tree to learn it would empty the table for the length of a second round trip.
348	// It is also what stops a create outliving a context switch from reloading the
349	// tree of the context it switched to.
350	//
351	// A failure goes to the footer rather than to m.error, which would replace the
352	// tree with an error screen — the one place the removed row cannot be seen.
353	func (m Model) handleGroupCreated(msg GroupCreatedMsg) (tea.Model, tea.Cmd) {
354		if msg.Error != nil {
355			log.Printf("ERROR [explorer] create namespace: %v", msg.Error)
356			m.settleCreating(msg.Target, nil)
357			return m, m.footer.Error("Failed to create " + msg.Target + " — check logs")
358		}
359	
360		node := nodeFromNamespace(msg.Namespace, nil)
361		m.settleCreating(msg.Target, node)
362		m.selectRow(node.FullPath)
363		return m, nil
364	}
365	
366	// handleProjectCreated resolves the placeholder row in place. See
367	// handleGroupCreated for why there is no refresh.
368	func (m Model) handleProjectCreated(msg ProjectCreatedMsg) (tea.Model, tea.Cmd) {
369		if msg.Error != nil {
370			log.Printf("ERROR [explorer] create repository: %v", msg.Error)
371			m.settleCreating(msg.Target, nil)
372			return m, m.footer.Error("Failed to create " + msg.Target + " — check logs")
373		}
374	
375		// The project exists whatever the template did, so the row settles either
376		// way; only the message differs.
377		node := nodeFromRepository(msg.Repository, nil)
378		m.settleCreating(msg.Target, node)
379		m.selectRow(node.FullPath)
380	
381		if msg.TemplateError != nil {
382			log.Printf("ERROR [explorer] apply template: %v", msg.TemplateError)
383			return m, m.footer.Warn(fmt.Sprintf("%s created, but the template did not apply — check logs", node.Name))
384		}
385		return m, nil
386	}

